export default function select({ body }) {
  const n = body?.note,
    id = body?.fileId;
  if (
    !id ||
    !n ||
    typeof n !== "object" ||
    typeof n.isArchived !== "boolean" ||
    typeof n.textContentHtml !== "string"
  )
    throw Error("Invalid Keep JSON or file ID");
  const eligible =
    !n.isArchived &&
    (n.textContentHtml.includes("dépensé") || n.textContentHtml.includes("depense"));
  if (!eligible) return { eligible: false, id, text: "", created: "", edited: "" };
  function time(x) {
    const n = Number(x);
    if (!Number.isSafeInteger(n) || n <= 0) throw Error("Invalid Keep timestamp");
    return new Date(n / 1000).toISOString();
  }
  if (typeof n.textContent !== "string") throw Error("Missing note text");
  return {
    eligible: true,
    id,
    text: n.textContent,
    created: time(n.createdTimestampUsec),
    edited: time(n.userEditedTimestampUsec),
  };
}

