export default async function plan(
  { id, text, created, edited, amount, values, sheet, acknowledge, resolution },
  ctx,
) {
  if (!/^[A-Za-z0-9_ -]+$/.test(sheet)) throw Error("Configure sheet name");
  const rows = values ?? [],
    header = rows[0] ?? [],
    expected = ["fileId", "textContent", "Edited", "Created", "isArchived", "Amount"];
  if (expected.some((v, i) => header[i] !== v))
    throw Error("Expected fileId, textContent, Edited, Created, isArchived, Amount headers");
  const matches = [];
  for (let i = 1; i < rows.length; i++) if (String(rows[i][0] ?? "") === id) matches.push(i + 1);
  if (matches.length > 1) throw Error("Duplicate fileId in sheet: " + id);
  const key = "keep:" + id,
    old = await ctx.state.get(key);
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect uncertain sheet write " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, null);
      return { write: false, update: false, key, range: "Sheet1!A1:F1", values: [] };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    write: true,
    update: matches.length === 1,
    key,
    range: "'" + sheet + "'!A" + (matches[0] ?? 1) + ":F" + (matches[0] ?? 1),
    values: [[id, text, edited, created, false, amount]],
  };
}

